export class Text extends Node {
  constructor(text: any) {
    super();
    this.nodeType = 3;
    this.nodeName = "#text";
    this.node_value = String(text);
  }
}

function updateElementStyles(element: Element, state: Record<string, any>) {
  let str = "";
  for (const key in state) {
    const value = state[key];
    if (typeof value !== "undefined" && value !== null && String(value).length > 0) {
      str += `${key}: ${state[key]};`;
    }
  }
  if (str.length === 0) {
    element.removeAttribute("style");
  } else {
    element.setAttribute("style", str);
  }
}

export class Element extends Node {
  #listeners: Map<string, Set<Function>> = new Map();
  #objectListeners = new WeakMap<object, Function>();
  protected get _listeners() {
    return this.#listeners;
  }
  #value: string = "";
  #checked: boolean = false;

  constructor() {
    super();
    this.nodeType = 1;
    this.attributes = [];
    this.childNodes = [];
  }

  get value(): string {
    if (this.#value.length > 0) {
      return this.#value;
    }
    const attributeValue = this.getAttribute("value");
    return attributeValue == null ? "" : String(attributeValue);
  }

  set value(val: string) {
    this.#value = String(val);
    if (this.#value.length === 0) {
      this.removeAttribute("value");
      return;
    }
    this.setAttribute("value", this.#value);
  }

  get checked(): boolean {
    return this.#checked || Boolean(this.getAttribute("checked"));
  }

  set checked(val: boolean) {
    this.#checked = Boolean(val);
    if (this.#checked) {
      this.setAttribute("checked", true);
    } else {
      this.removeAttribute("checked");
    }
  }

  addEventListener(
    type: "click",
    callback: LocalEventListener<MouseEvent> | null,
    options?: boolean | AddEventListenerOptions
  ): void;
  addEventListener(
    type: "submit",
    callback: LocalEventListener<SubmitEvent> | null,
    options?: boolean | AddEventListenerOptions
  ): void;
  addEventListener(
    type: string,
    callback: LocalEventListener | null,
    options?: boolean | AddEventListenerOptions
  ): void;
  addEventListener(
    type: string,
    callback: LocalEventListener<any> | null,
    _options?: boolean | AddEventListenerOptions | undefined
  ): void {
    if (!callback) return;
    let handler: Function | undefined;
    if (typeof callback === "function") {
      handler = callback;
    } else {
      handler = this.#objectListeners.get(callback);
      if (!handler) {
        handler = (event: Event) => callback.handleEvent(event);
        this.#objectListeners.set(callback, handler);
      }
    }
    if (!handler) return;

    let listeners = this.#listeners.get(type);
    if (!listeners) {
      listeners = new Set();
      this.#listeners.set(type, listeners);
    }
    listeners.add(handler);
  }

  removeEventListener(
    type: string,
    callback: LocalEventListener | null,
    _options?: boolean | EventListenerOptions | undefined
  ): void {
    if (!callback) return;
    const handler = typeof callback === "function" ? callback : this.#objectListeners.get(callback);
    if (!handler) return;

    const listeners = this.#listeners.get(type);
    if (listeners?.delete(handler) && listeners.size === 0) {
      this.#listeners.delete(type);
    }
  }

  _style = new Proxy(
    {},
    {
      get: (state: Record<string, any>, prop: string) => state[prop],
      set: (state: Record<string, any>, prop: string, value: any) => {
        state[prop] = value;
        updateElementStyles(this, state);
        return true;
      },
      deleteProperty: (state: Record<string, any>, prop: string) => {
        Reflect.deleteProperty(state, prop);
        updateElementStyles(this, state);
        return true;
      }
    }
  );

  get style() {
    return this._style as any;
  }

  set style(value: string) {
    if (isString(value)) {
      // should match pairs like "color: red; font-size: 12px; background: url(http://example.com/image.png?s=1024x1024&amp;w=is&amp;k=20&amp;c=ASa_AG8uP5Di7azXgJraSA6ME7fbLB0GX4YT_OzCARI=);"
      const regex = /([^:\s]+):\s*((url\([^)]+\))|[^;]+(?=(;|$)))/g;
      let match;

      while ((match = regex.exec(value)) !== null) {
        this._style[match[1]] = match[2].trim();
      }

      return;
    }

    throw new Error("Cannot set style");
  }

  get className(): string {
    return this.getAttribute("class") || "";
  }

  set className(value: string | boolean) {
    if (value == null || value === false) {
      this.removeAttribute("class");
    } else {
      this.setAttribute("class", String(value));
    }
  }

  classList = {
    toggle: (item: any, force: any) => {
      if (item) {
        const classes = (this.className || "").split(" ");
        const itemIndex = classes.indexOf(item);
        if (force && itemIndex === -1) {
          classes.push(item);
        }

        if (!force && itemIndex !== -1) {
          classes.splice(itemIndex, 1);
        }

        const final = classes.join(" ").trim();
        if (final.length) {
          this.className = classes.join(" ").trim();
        } else {
          this.className = false;
        }
      }
    }
  };

  get id(): string {
    return this.getAttribute("id") || "";
  }

  set id(value: string | boolean) {
    if (value == null || value === false) {
      this.removeAttribute("id");
    } else {
      this.setAttribute("id", String(value));
    }
  }

  set textContent(text) {
    this.nodeValue = String(text);
    this.childNodes = this.nodeValue ? [new Text(this.nodeValue)] : [];
  }
  get textContent() {
    const { childNodes } = this;
    if (childNodes.length === 0) {
      return this.nodeValue;
    }

    let text = "";
    for (let i = 0, l = childNodes.length; i < l; i++) {
      text += childNodes[i].textContent || childNodes[i].nodeValue || "";
    }
    return text;
  }

  set innerText(text) {
    this.nodeValue = String(text);
  }

  get innerText() {
    return this.nodeValue;
  }

  get innerHTML() {
    let str = "";
    for (let i = 0, l = this.childNodes.length; i < l; i++) {
      // console.log("domToHtml", this.childNodes[i], domToHtml(this.childNodes[i] as Element));
      str += domToHtml(this.childNodes[i] as Element);
    }
    return str;
  }

  set innerHTML(html) {
    this.textContent = "";
    if (html.length === 0) {
      return;
    }
    const result = htmlToDom(html);
    if (result instanceof DocumentFragment) {
      const children = Array.from(result.childNodes);
      for (const child of children) {
        this.appendChild(child);
      }
    } else {
      this.appendChild(result);
    }
  }

  get outerHTML(): string {
    return domToHtml(this);
  }

  querySelector(selector: string): Element | null {
    return querySelectorWithin(this, selector, 1)[0] ?? null;
  }

  querySelectorAll(selector: string): Element[] {
    return querySelectorWithin(this, selector);
  }

  click(): void {
    const tag = this.nodeName.toLowerCase();
    if ((tag === "button" || tag === "input") && this.hasAttribute("disabled")) {
      return;
    }
    this.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, button: 0 }));
  }
}

export class HTMLFormElement extends Element {
  requestSubmit(submitter: Element | null = null): void {
    this.dispatchEvent(
      new SubmitEvent("submit", {
        bubbles: true,
        cancelable: true,
        submitter: submitter as unknown as HTMLElement | null
      })
    );
  }
}

export class DocumentFragment extends Element {
  constructor() {
    super();
    this.nodeType = 11;
    this.nodeName = "#document-fragment";
  }
}

export class Document extends Element {
  constructor() {
    super();
    this.nodeType = 9;
    this.nodeName = "#document";
    this.documentElement = this.createElement("html");
    this.head = this.createElement("head");
    this.body = this.createElement("body");
    this.documentElement.appendChild(this.head);
    this.documentElement.appendChild(this.body);
    this.appendChild(this.documentElement);
  }

  documentElement: Element;
  head: Element;
  body: Element;
  location?: Location;

  getElementById(id: string): Element | null {
    const stack = Array.from(this.childNodes).reverse();
    while (stack.length > 0) {
      const node = stack.pop() as Node;
      if (!(node instanceof Element)) {
        continue;
      }
      if (node.getAttribute("id") === id) {
        return node;
      }
      for (let index = node.childNodes.length - 1; index >= 0; index--) {
        stack.push(node.childNodes[index]);
      }
    }
    return null;
  }

  createDocumentFragment(): DocumentFragment {
    return new DocumentFragment();
  }

  createElement(type: "form"): HTMLFormElement;
  createElement(type: string): Element;
  createElement(type: string): Element {
    const element = type.toLowerCase() === "form" ? new HTMLFormElement() : new Element();
    element.nodeName = type.toUpperCase();
    return element;
  }

  createElementNS(ns: string, type: string) {
    const element = this.createElement(type);
    element.baseURI = ns;
    return element;
  }

  createTextNode(text: any) {
    return new Text(text);
  }
}

type SimpleSelector = {
  tag: string | null;
  id: string | null;
  className: string | null;
  attribute: string | null;
  attributeValue: string | null;
};

function parseSimpleSelector(selector: string): SimpleSelector {
  const match = selector.match(
    /^(?:([A-Za-z][A-Za-z0-9-]*))?(?:(#[A-Za-z_][A-Za-z0-9_-]*)|(\.[A-Za-z_][A-Za-z0-9_-]*)|\[([A-Za-z_][A-Za-z0-9_-]*)(?:="([^"]*)")?\])?$/
  );
  if (!match || (!match[1] && !match[2] && !match[3] && !match[4])) {
    throw new SyntaxError(`Unsupported selector: ${selector}`);
  }
  return {
    tag: match[1]?.toLowerCase() ?? null,
    id: match[2]?.slice(1) ?? null,
    className: match[3]?.slice(1) ?? null,
    attribute: match[4] ?? null,
    attributeValue: typeof match[5] === "string" ? match[5] : null
  };
}

function parseSelector(selector: string): SimpleSelector[] {
  if (selector.trim() !== selector || selector.length === 0 || /\s{2,}/.test(selector)) {
    throw new SyntaxError(`Unsupported selector: ${selector}`);
  }
  return selector.split(" ").map(parseSimpleSelector);
}

function matchesSimpleSelector(element: Element, selector: SimpleSelector): boolean {
  if (selector.tag && element.nodeName.toLowerCase() !== selector.tag) {
    return false;
  }
  if (selector.id && element.id !== selector.id) {
    return false;
  }
  if (selector.className && !element.className.split(/\s+/).includes(selector.className)) {
    return false;
  }
  if (selector.attribute) {
    const attributeValue = element.getAttribute(selector.attribute);
    if (attributeValue === null) {
      return false;
    }
    if (selector.attributeValue !== null) {
      return attributeValue === selector.attributeValue;
    }
  }
  return true;
}

function querySelectorWithin(root: Node, selector: string, limit = Number.POSITIVE_INFINITY): Element[] {
  const parts = parseSelector(selector);
  const targetSelector = parts[parts.length - 1];
  const matches: Element[] = [];
  const stack = Array.from(root.childNodes).reverse();

  while (stack.length > 0) {
    const node = stack.pop() as Node;
    if (!(node instanceof Element)) {
      continue;
    }
    if (matchesSimpleSelector(node, targetSelector)) {
      let ancestor = node.parentElement;
      let partIndex = parts.length - 2;
      while (partIndex >= 0 && ancestor) {
        if (matchesSimpleSelector(ancestor, parts[partIndex])) {
          partIndex--;
        }
        ancestor = ancestor.parentElement;
      }
      if (partIndex < 0) {
        matches.push(node);
        if (matches.length === limit) {
          return matches;
        }
      }
    }
    for (let index = node.childNodes.length - 1; index >= 0; index--) {
      stack.push(node.childNodes[index]);
    }
  }
  return matches;
}

const ESCAPE_LOOKUP: { [key: string]: string } = {
  "&": "&amp;",
  ">": "&gt;",
  "<": "&lt;",
  '"': "&quot;",
  "'": "&#39;"
};

const ESCAPE_REGEX = /[&><"']/g;

function escapeHtml(str: string | any): string {
  if (typeof str !== "string") {
    return String(str);
  }

  if (ESCAPE_REGEX.test(str) === false) {
    return str;
  }

  return str.replace(ESCAPE_REGEX, (match) => ESCAPE_LOOKUP[match]).replace(/&amp;amp;/g, "&amp;");
}

const selfClosingTags = [
  "area",
  "base",
  "br",
  "col",
  "embed",
  "hr",
  "img",
  "input",
  "link",
  "meta",
  "param",
  "source",
  "track",
  "wbr",
  "!doctype"
];

const rawTextTags = ["script", "style"];

export function domToHtml(dom: Element | Text | DocumentFragment, rawText = false): string {
  if (dom.nodeType === 3) {
    return rawText ? dom.textContent : escapeHtml(dom.textContent);
  }

  if (dom.nodeType === 1) {
    const name = dom.nodeName.toLowerCase();
    let str = "<" + name;

    for (let i = 0, l = dom.attributes.length; i < l; i++) {
      const attr = dom.attributes[i];
      str += " " + attr.nodeName + '="' + escapeHtml(attr.nodeValue) + '"';
    }

    if (selfClosingTags.indexOf(name) === -1) {
      str += ">";
      if (dom.childNodes && dom.childNodes.length > 0) {
        for (let i = 0, l = dom.childNodes.length; i < l; i++) {
          const child = domToHtml(dom.childNodes[i] as Element, rawTextTags.includes(name));
          if (child) {
            str += child;
          }
        }
      }
      str += "</" + name + ">";
    } else {
      str += "/>";
    }

    return str;
  }

  return "";
}

export function domToHyperscript(childNodes: ChildNodes, depth = 1) {
  let spaces = "";
  for (let i = 0; i < depth; i++) {
    spaces += "  ";
  }

  return childNodes
    .map((item) => {
      if (item.nodeType === 10) {
        return `\n${spaces}"<!DOCTYPE html>"`;
      } else if (item.nodeType === 3) {
        return `\n${spaces}"${item.nodeValue}"`;
      } else {
        let str = `\n${spaces}v("${item.nodeName.toLowerCase()}", `;

        if (item.attributes) {
          const attrs: Record<string, any> = {};
          for (let i = 0, l = item.attributes.length; i < l; i++) {
            const attr = item.attributes[i];
            attrs[attr.nodeName] = attr.nodeValue;
          }
          str += JSON.stringify(attrs);
        } else {
          str += "{}";
        }

        str += ", [";
        if (item.childNodes && item.childNodes.length > 0) {
          str += `${domToHyperscript(item.childNodes as unknown as Element[], depth + 1)}\n${spaces}`;
        }

        str += `])`;
        return str;
      }
    })
    .join(",");
}

interface ObjectIndexItem {
  tagName: string;
  startsAt: number;
  endsAt: number | null;
  contentStartsAt: number;
  contentEndsAt: number | null;
  attributes: { [key: string]: any };
  children: ObjectIndexItem[];
  nodeValue: string | null;
}

interface ObjectIndexItemWithContent extends ObjectIndexItem {
  endsAt: number;
  contentEndsAt: number;
  children: ObjectIndexItemWithContent[];
}

interface ObjectIndexList extends Array<ObjectIndexItem> {}

const MAX_HTML_PARSER_DEPTH = 15000;
const MAX_HTML_PARSER_NODES = 100000;

function assertParserDepth(depth: number) {
  if (depth > MAX_HTML_PARSER_DEPTH) {
    throw new Error("HTML input exceeds maximum parser depth");
  }
}

function assertParserNodes(nodes: number) {
  if (nodes > MAX_HTML_PARSER_NODES) {
    throw new Error("HTML input exceeds maximum parser nodes");
  }
}

function createTextIndexItem(startsAt: number, endsAt: number, nodeValue: string): ObjectIndexItemWithContent {
  return {
    tagName: "#text",
    startsAt,
    endsAt,
    contentStartsAt: startsAt,
    contentEndsAt: endsAt,
    attributes: {},
    children: [],
    nodeValue
  };
}

function findTexts(item: ObjectIndexItemWithContent, html: string) {
  const stack = [item];

  while (stack.length) {
    const current = stack.pop() as ObjectIndexItemWithContent;
    const originalChildren = current.children;
    const newChildren: ObjectIndexItemWithContent[] = [];

    if (originalChildren.length) {
      for (let i = 0; i < originalChildren.length; i++) {
        const child = originalChildren[i];
        const nextChild = originalChildren[i + 1];

        if (i === 0 && child.startsAt > current.contentStartsAt) {
          const childContent = html.substring(current.contentStartsAt, child.startsAt);
          newChildren.push(
            createTextIndexItem(current.contentStartsAt, current.contentStartsAt + childContent.length, childContent)
          );
        }

        newChildren.push(child);

        if (nextChild && child.endsAt < nextChild.startsAt) {
          const childContent = html.substring(child.endsAt, nextChild.startsAt);
          newChildren.push(createTextIndexItem(child.endsAt, child.endsAt + childContent.length, childContent));
        }

        if (!nextChild && child.endsAt < current.contentEndsAt) {
          const childContent = html.substring(child.endsAt, current.contentEndsAt);
          newChildren.push(createTextIndexItem(child.endsAt, current.contentEndsAt, childContent));
        }
      }

      for (let i = originalChildren.length - 1; i >= 0; i--) {
        stack.push(originalChildren[i]);
      }
    } else {
      const childContent = html.substring(current.contentStartsAt, current.contentEndsAt);

      if (childContent.length) {
        newChildren.push(createTextIndexItem(current.contentStartsAt, current.contentEndsAt, childContent));
      }
    }

    current.children = newChildren;
  }
}

function createDomNode<T extends Node>(item: ObjectIndexItemWithContent): T {
  if (item.tagName === "#text") {
    return document.createTextNode(item.nodeValue as string) as unknown as T;
  }

  const node = (item.tagName === "#document-fragment"
    ? document.createDocumentFragment()
    : document.createElement(item.tagName)) as unknown as T;

  for (const key in item.attributes) {
    node.setAttribute(key, item.attributes[key]);
  }

  return node;
}

function convertToDom<T extends Node>(item: ObjectIndexItemWithContent): T {
  const node = createDomNode<T>(item);
  const stack: { item: ObjectIndexItemWithContent; parent: Node }[] = item.children
    .map((child) => ({ item: child, parent: node }))
    .reverse();

  while (stack.length) {
    const current = stack.pop() as { item: ObjectIndexItemWithContent; parent: Node };
    const childNode = createDomNode(current.item);

    current.parent.appendChild(childNode);

    for (let i = current.item.children.length - 1; i >= 0; i--) {
      stack.push({ item: current.item.children[i], parent: childNode });
    }
  }

  return node;
}

// eslint-disable-next-line sonarjs/cognitive-complexity
function getObjectIndexTree(html: string): DocumentFragment {
  let item;
  const regex = RegExp("<([^>|^!]+)>", "g");
  const items: ObjectIndexList = [];
  const openItems: ObjectIndexList = [];
  let nodeCount = 0;

  // Make the initial list of items.
  while ((item = regex.exec(html))) {
    // If is a closing tag
    if (item[0].startsWith("</")) {
      const lastOpenedItem = openItems.pop();
      if (lastOpenedItem) {
        lastOpenedItem.endsAt = item.index + item[0].length;
        lastOpenedItem.contentEndsAt = item.index;

        // Find the last opened item again, this will be the parent of the current item.
        const parent = openItems[openItems.length - 1];
        if (parent) {
          // Add the last opened item as a child of the parent.
          parent.children.push(lastOpenedItem);
        } else {
          items.push(lastOpenedItem);
        }
      }

      continue;
    }

    // If is an opening tag
    const element: ObjectIndexItem = {
      tagName: item[1].split(" ")[0],
      startsAt: item.index,
      endsAt: null,
      contentStartsAt: item.index + item[0].length,
      contentEndsAt: null,
      attributes: {},
      children: [],
      nodeValue: null
    };

    nodeCount++;
    assertParserNodes(nodeCount);

    // Find the attributes of the tag.
    let string = (item[1] || "").substring(element.tagName.length + 1).replace(/\/$/g, "");
    const attributesWithValues = string.match(/\S+="[^"]+"/g);

    if (attributesWithValues) {
      for (const attribute of attributesWithValues) {
        const [name, ...value] = attribute.trim().split("=");
        string = string.replace(attribute, "");
        if (value) {
          element.attributes[name] = value.join("=").replace(/(^"|"$)/g, "");
        }
      }
    }

    const attributesWithBooleanValues = string.match(/\s\S+=[^"]+/g);
    if (attributesWithBooleanValues) {
      for (const attribute of attributesWithBooleanValues) {
        const [name, ...value] = attribute.trim().split("=");
        string = string.replace(attribute, "");
        if (value) {
          element.attributes[name] = value.join("=").replace(/(^"|"$)/g, "");
        }
      }
    }

    const attributesWithEmptyValues = string.match(/\s?\S+/g);
    if (attributesWithEmptyValues) {
      for (const attribute of attributesWithEmptyValues) {
        const name = attribute.trim();
        element.attributes[name] = true;
      }
    }

    // If the tag is self closing
    if (item[0].endsWith("/>")) {
      assertParserDepth(openItems.length + 1);
      element.endsAt = element.startsAt + item[0].length;
      element.contentStartsAt = element.contentEndsAt = element.endsAt;

      // Find the last opened item, this will be the parent of the current item.
      const parent = openItems[openItems.length - 1];
      if (parent) {
        // Add the last opened item as a child of the parent.
        parent.children.push(element);
        continue;
      }
    }

    if (item[0].endsWith("/>")) {
      items.push(element);
    } else {
      assertParserDepth(openItems.length + 1);
      openItems.push(element);
    }
  }

  while (openItems.length) {
    const openItem = openItems.pop() as ObjectIndexItem;
    openItem.endsAt = html.length;
    openItem.contentEndsAt = html.length;

    const parent = openItems[openItems.length - 1];
    if (parent) {
      parent.children.push(openItem);
    } else {
      items.push(openItem);
    }
  }

  const fragmentItem: ObjectIndexItemWithContent = {
    tagName: "#document-fragment",
    startsAt: 0,
    endsAt: html.length,
    contentStartsAt: 0,
    contentEndsAt: html.length,
    attributes: {},
    children: items as ObjectIndexItemWithContent[],
    nodeValue: null
  };

  findTexts(fragmentItem, html);

  return convertToDom<DocumentFragment>(fragmentItem);
}

// First we create a tree of object indexes from the HTML string.
// The resulting array is then reordered to match the order of the html string.
// And to move the children to the correct position in its parents.
// This resulting array is populated with a object node version of the object index.
// If the final result have more than 1 node, then return a document fragment node.
// If the final result have 1 node, then return the node.
// eslint-disable-next-line complexity
export function htmlToDom(html: string): Element | Text | DocumentFragment {
  // Search for the opening and closing tags of the root element.
  // The opening tag could be in the middle of the string, so we need to
  // search for the first opening tag.
  const openingTag = html.match(/<[^>]+>/g);

  const document = new Document();

  // If the opening tag is not found, return a document fragment node with the html string as text content.
  if (!openingTag) {
    const documentFragment = document.createDocumentFragment();
    documentFragment.appendChild(document.createTextNode(html));
    return documentFragment;
  }

  const fragment = getObjectIndexTree(html);

  if (fragment.childNodes.length > 1) {
    return fragment;
  }

  return fragment.childNodes[0];
}

export function htmlToHyperscript(html: string) {
  const domTree = htmlToDom(html);
  const hyperscript = domToHyperscript(domTree instanceof DocumentFragment ? domTree.childNodes : [domTree]);
  return `[${hyperscript}\n]`;
}

export const document = new Document();
